def filter_queryset_by_locale(qs, locale_code: Optional[str]):
    """Filter a page queryset by locale code; return empty queryset if locale is invalid."""
    if not locale_code:
        return qs
    try:
        return qs.filter(locale=resolve_locale(locale_code))
    except HttpError:
        return qs.none()

