def _serialize_links(links):
    if not links:
        return []
    result = []
    for link in links:
        if hasattr(link, 'model_dump'):
            result.append(link.model_dump(exclude_none=True))
        elif hasattr(link, 'dict'):
            result.append(link.dict(exclude_none=True))
        else:
            result.append(link)
    return result

