        if (self._page._meta.label_lower, name) in EDITORIAL_FIELDS:
            return resolve_editorial(self._page, name)
        raise AttributeError(
            f"{name!r} is not a migrated editorial field for "
            f"{self._page._meta.label_lower}"
        )

