def _push_internal_links_metafield(shop, owner_gid, page):
    """Push semantic internal links as JSON metafield (default custom.internal_links)."""
    from django.conf import settings

    from shopify_content.semantic_links.serialization import serialize_semantic_links

    links = serialize_semantic_links(page)
    if not links:
        return True
    namespace = getattr(settings, 'SEMANTIC_LINKS_METAFIELD_NAMESPACE', 'custom')
    key = getattr(settings, 'SEMANTIC_LINKS_METAFIELD_KEY', 'internal_links')
    return _push_metafields(shop, [{
        'ownerId': owner_gid,
        'namespace': namespace,
        'key': key,
        'type': 'json',
        'value': json.dumps(links, ensure_ascii=False),
    }])

def _push_native_reference_metafields(shop, owner_gid, page):
    """Push typed FK relations as native list.*_reference metafields (parallel to JSON)."""
    from django.conf import settings

    if not getattr(settings, 'SEMANTIC_LINKS_NATIVE_REFS_ENABLED', True):
        return True

    from shopify_content.semantic_links.constants import NATIVE_REFERENCE_CONFIG
    from shopify_content.semantic_links.references import (
        format_list_reference_value,
        serialize_native_references,
    )

    refs = serialize_native_references(page)
    if not refs:
        return True

    namespace = getattr(settings, 'SEMANTIC_LINKS_NATIVE_REFS_NAMESPACE', 'custom')
    inputs = []
    for relation_name, gids in refs.items():
        config = NATIVE_REFERENCE_CONFIG[relation_name]
        inputs.append({
            'ownerId': owner_gid,
            'namespace': namespace,
            'key': config['metafield_key'],
            'type': config['shopify_type'],
            'value': format_list_reference_value(gids),
        })
    return _push_metafields(shop, inputs)

def _push_seo_metafields(shop, owner_gid, seo_title, seo_description):
    """
    Push SEO data as Shopify metafields.
    Used for Article and Blog which have no native seo field in Admin API.
    """
    inputs = []
    if seo_title:
        inputs.append({
            'ownerId': owner_gid,
            'namespace': 'global',
            'key': 'title_tag',
            'type': 'single_line_text_field',
            'value': seo_title,
        })
    if seo_description:
        inputs.append({
            'ownerId': owner_gid,
            'namespace': 'global',
            'key': 'description_tag',
            'type': 'single_line_text_field',
            'value': seo_description,
        })
    return _push_metafields(shop, inputs)

